import { AnimatePresence, motion } from 'framer-motion';
import { serviceStages } from '../../data/siteContent.js';
import BlueprintGraph from './BlueprintGraph.jsx';
import IDEWindow from './IDEWindow.jsx';
import BuildPipeline from './BuildPipeline.jsx';
import SandboxPreview from './SandboxPreview.jsx';

const phaseComponents = [
  BlueprintGraph,
  IDEWindow,
  BuildPipeline,
  SandboxPreview,
];

export default function ScrollSyncCanvas({
  service,
  phase,
  phaseProgress,
  isReducedMotion,
}) {
  const ActiveComponent = phaseComponents[phase] || BlueprintGraph;
  const stage = serviceStages[phase] || serviceStages[0];

  return (
    <div className="glass-panel flex h-full min-h-[560px] flex-col rounded-[8px] p-4 md:p-5">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-4">
        <div>
          <p className="text-xs font-black uppercase text-ember">
            {stage.eyebrow}
          </p>
          <h3 className="mt-2 text-2xl font-black text-white">{stage.label}</h3>
        </div>
        <div className="flex gap-1 rounded-full border border-white/10 bg-white/[0.045] p-1">
          {serviceStages.map((item, index) => (
            <span
              key={item.id}
              className={`rounded-full px-3 py-1.5 text-[0.68rem] font-black uppercase ${
                index === phase
                  ? 'bg-plasma text-void'
                  : 'text-white/42'
              }`}
            >
              {item.shortLabel}
            </span>
          ))}
        </div>
      </div>

      <div className="min-h-0 flex-1">
        <AnimatePresence mode="wait">
          <motion.div
            key={`${service.id}-${phase}`}
            initial={{ opacity: 0, y: isReducedMotion ? 0 : 18, scale: 0.985 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: isReducedMotion ? 0 : -14, scale: 0.985 }}
            transition={{ duration: 0.34, ease: [0.22, 1, 0.36, 1] }}
            className="h-full"
          >
            <ActiveComponent
              service={service}
              phaseProgress={phaseProgress}
              isReducedMotion={isReducedMotion}
            />
          </motion.div>
        </AnimatePresence>
      </div>

      <p className="mt-4 text-sm leading-6 text-white/58">{stage.description}</p>
    </div>
  );
}
