import { motion } from 'framer-motion';
import { Cloud, Database, Hexagon, Layers3, Server, UserRound } from 'lucide-react';

const nodeIcons = [UserRound, Layers3, Server, Database, Cloud, Hexagon];
const positions = [
  { x: 13, y: 34 },
  { x: 34, y: 18 },
  { x: 55, y: 34 },
  { x: 36, y: 68 },
  { x: 72, y: 18 },
  { x: 80, y: 66 },
];

export default function BlueprintGraph({ service, phaseProgress, isReducedMotion }) {
  const safeProgress = isReducedMotion ? 1 : Math.max(0.12, phaseProgress);
  const visibleLinks = Math.ceil(safeProgress * (positions.length - 1));

  return (
    <div className="relative h-full min-h-[420px] overflow-hidden rounded-[8px] border border-white/10 bg-void/50 p-4 scanline">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_45%,rgba(82,211,216,0.15),transparent_34rem)]" />
      <svg
        className="absolute inset-0 h-full w-full"
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        aria-hidden="true"
      >
        {positions.slice(0, -1).map((start, index) => {
          const end = positions[index + 1];
          const active = index < visibleLinks;

          return (
            <motion.line
              key={`${start.x}-${end.x}`}
              x1={start.x}
              y1={start.y}
              x2={end.x}
              y2={end.y}
              stroke={active ? service.accent : 'rgba(255,255,255,0.12)'}
              strokeWidth={active ? 0.48 : 0.22}
              strokeDasharray="3 2"
              initial={{ pathLength: 0, opacity: 0.2 }}
              animate={{ pathLength: active ? 1 : 0.25, opacity: active ? 0.9 : 0.25 }}
              transition={{ duration: 0.72, ease: 'easeOut' }}
            />
          );
        })}
      </svg>

      {service.blueprintNodes.map((label, index) => {
        const Icon = nodeIcons[index % nodeIcons.length];
        const position = positions[index % positions.length];
        const active = index <= visibleLinks;

        return (
          <motion.div
            key={label}
            className="absolute grid h-20 w-20 place-items-center rounded-full border border-white/12 bg-midnight/80 text-center shadow-glow backdrop-blur-md"
            style={{
              left: `${position.x}%`,
              top: `${position.y}%`,
              transform: 'translate(-50%, -50%)',
            }}
            initial={{ scale: 0.72, opacity: 0 }}
            animate={{
              scale: active ? 1 : 0.88,
              opacity: active ? 1 : 0.42,
              boxShadow: active
                ? `0 0 42px ${service.accent}55`
                : '0 0 20px rgba(255,255,255,0.08)',
            }}
            transition={{ delay: isReducedMotion ? 0 : index * 0.07, duration: 0.45 }}
          >
            <Icon className="mb-1 h-5 w-5 text-plasma" aria-hidden="true" />
            <span className="px-2 text-[0.67rem] font-black uppercase text-white/82">
              {label}
            </span>
          </motion.div>
        );
      })}

      <div className="absolute bottom-4 left-4 right-4 rounded-[8px] border border-white/10 bg-void/72 p-4 backdrop-blur-md">
        <p className="text-xs font-black uppercase text-ember">
          Discovery / Design
        </p>
        <p className="mt-2 text-sm leading-6 text-white/72">
          {service.outcome}
        </p>
      </div>
    </div>
  );
}
