import { useEffect, useMemo, useState } from 'react';
import {
  Activity,
  ArrowRight,
  Bot,
  BrainCircuit,
  Check,
  DatabaseZap,
  Gauge,
  MessageSquareText,
  MousePointer2,
  RotateCcw,
  Smartphone,
  Workflow,
} from 'lucide-react';
import { motion } from 'framer-motion';

function DashboardSandbox({ service }) {
  const [mode, setMode] = useState('Observe');
  const [load, setLoad] = useState(64);

  return (
    <div className="grid h-full gap-4 md:grid-cols-[0.8fr_1fr]">
      <div className="rounded-[8px] border border-white/10 bg-white/[0.045] p-4">
        <div className="flex items-center justify-between">
          <span className="text-sm font-black text-white">{service.sandbox.label}</span>
          <Gauge className="h-5 w-5 text-plasma" aria-hidden="true" />
        </div>
        <div className="mt-8 text-6xl font-black text-white">{load}%</div>
        <p className="mt-2 text-sm text-white/58">Operational confidence</p>
        <label className="mt-8 block text-xs font-black uppercase text-white/48">
          Load
          <input
            type="range"
            min="28"
            max="96"
            value={load}
            onChange={(event) => setLoad(event.target.value)}
            className="mt-4 w-full accent-ember"
          />
        </label>
      </div>
      <div className="grid gap-3">
        {['Orders', 'Revenue', 'Risk'].map((item, index) => (
          <motion.button
            type="button"
            key={item}
            onClick={() => setMode(item)}
            whileTap={{ scale: 0.98 }}
            className="flex items-center justify-between rounded-[8px] border border-white/10 bg-white/[0.045] p-4 text-left hover:border-plasma/45"
          >
            <span>
              <span className="block font-black text-white">{item}</span>
              <span className="block text-sm text-white/52">
                {mode === item ? 'Active signal' : 'Ready for inspection'}
              </span>
            </span>
            <span className="text-2xl font-black text-plasma">
              {Math.round(Number(load) - index * 9)}
            </span>
          </motion.button>
        ))}
      </div>
    </div>
  );
}

function MobileSandbox() {
  const [gesture, setGesture] = useState(48);

  return (
    <div className="grid h-full gap-5 md:grid-cols-[0.74fr_1fr] md:items-center">
      <div className="mx-auto h-[360px] w-[190px] rounded-[2rem] border border-white/18 bg-[#081526] p-3 shadow-glow">
        <div className="h-full rounded-[1.45rem] border border-white/10 bg-gradient-to-b from-electric/30 via-void to-ember/20 p-4">
          <div className="mx-auto mb-5 h-1.5 w-16 rounded-full bg-white/22" />
          <div
            className="rounded-[8px] border border-white/14 bg-white/[0.08] p-3 transition"
            style={{ transform: `translateX(${(gesture - 50) / 5}px)` }}
          >
            <Smartphone className="h-5 w-5 text-plasma" aria-hidden="true" />
            <p className="mt-8 text-xl font-black text-white">Sync flow</p>
            <p className="mt-2 text-xs leading-5 text-white/58">
              Offline queue ready. Gesture latency stays under budget.
            </p>
          </div>
        </div>
      </div>
      <div>
        <p className="text-xs font-black uppercase text-ember">
          Touch model
        </p>
        <h3 className="mt-3 text-3xl font-black text-white">Slide gesture</h3>
        <p className="mt-3 text-sm leading-6 text-white/64">
          Adjust the gesture value to move the product card and test how a
          mobile state responds across the flow.
        </p>
        <input
          type="range"
          min="0"
          max="100"
          value={gesture}
          onChange={(event) => setGesture(event.target.value)}
          className="mt-8 w-full accent-plasma"
          aria-label="Slide gesture intensity"
        />
      </div>
    </div>
  );
}

function ModernisationSandbox() {
  const [modern, setModern] = useState(false);

  return (
    <div className="grid h-full gap-4 md:grid-cols-2">
      {['Legacy Layer', 'Modern Layer'].map((label, index) => {
        const active = modern === Boolean(index);
        return (
          <button
            type="button"
            key={label}
            onClick={() => setModern(Boolean(index))}
            className={`rounded-[8px] border p-5 text-left transition ${
              active
                ? 'border-plasma/55 bg-plasma/10'
                : 'border-white/10 bg-white/[0.04]'
            }`}
          >
            <RotateCcw className="h-5 w-5 text-ember" aria-hidden="true" />
            <h3 className="mt-5 text-2xl font-black text-white">{label}</h3>
            <p className="mt-3 text-sm leading-6 text-white/62">
              {index === 0
                ? 'Tightly coupled modules, manual checks, unclear ownership.'
                : 'Typed boundaries, contract tests, staged releases, live telemetry.'}
            </p>
            <div className="mt-6 h-2 overflow-hidden rounded-full bg-white/10">
              <div
                className="h-full rounded-full bg-gradient-to-r from-ember to-plasma"
                style={{ width: index === 0 ? '42%' : '84%' }}
              />
            </div>
          </button>
        );
      })}
    </div>
  );
}

function AutomationSandbox() {
  const [running, setRunning] = useState(false);
  const steps = ['Collect', 'Validate', 'Update ERP', 'Audit'];

  useEffect(() => {
    if (!running) return undefined;
    const timer = window.setTimeout(() => setRunning(false), 1800);
    return () => window.clearTimeout(timer);
  }, [running]);

  return (
    <div className="h-full rounded-[8px] border border-white/10 bg-white/[0.035] p-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-xs font-black uppercase text-ember">
            RPA Workflow Runner
          </p>
          <h3 className="mt-2 text-3xl font-black text-white">Run workflow</h3>
        </div>
        <button
          type="button"
          onClick={() => setRunning(true)}
          className="inline-flex h-11 items-center gap-2 rounded-full bg-ember px-4 text-sm font-black text-void"
        >
          <Bot className="h-4 w-4" aria-hidden="true" />
          Run Bot
        </button>
      </div>
      <div className="mt-8 grid gap-3 md:grid-cols-4">
        {steps.map((step, index) => (
          <motion.div
            key={step}
            animate={{
              y: running ? [0, -8, 0] : 0,
              borderColor: running ? '#52D3D8' : 'rgba(255,255,255,0.1)',
            }}
            transition={{ delay: index * 0.15, duration: 0.55 }}
            className="rounded-[8px] border bg-void/48 p-4"
          >
            <Workflow className="h-5 w-5 text-plasma" aria-hidden="true" />
            <p className="mt-6 font-black text-white">{step}</p>
            <p className="mt-2 text-xs leading-5 text-white/52">
              {running ? 'Processing' : 'Waiting'}
            </p>
          </motion.div>
        ))}
      </div>
    </div>
  );
}

function AiSandbox() {
  const [asked, setAsked] = useState(false);
  const recommendation = useMemo(
    () =>
      asked
        ? 'Prioritise verified records, human review, and assisted next actions.'
        : 'Ask the assistant to generate a decision brief.',
    [asked],
  );

  return (
    <div className="grid h-full gap-4 md:grid-cols-[0.86fr_1fr]">
      <div className="rounded-[8px] border border-white/10 bg-white/[0.045] p-5">
        <BrainCircuit className="h-8 w-8 text-plasma" aria-hidden="true" />
        <h3 className="mt-5 text-3xl font-black text-white">
          AI Decision Assistant
        </h3>
        <p className="mt-4 text-sm leading-6 text-white/62">
          The assistant uses verified context, guardrails, and review steps to
          keep the response useful and accountable.
        </p>
        <button
          type="button"
          onClick={() => setAsked((current) => !current)}
          className="mt-7 inline-flex h-11 items-center gap-2 rounded-full bg-plasma px-4 text-sm font-black text-void"
        >
          <MessageSquareText className="h-4 w-4" aria-hidden="true" />
          Ask assistant
        </button>
      </div>
      <div className="rounded-[8px] border border-white/10 bg-[#06101f] p-5">
        <p className="text-xs font-black uppercase text-ember">
          Assistive brief
        </p>
        <p className="mt-5 text-xl font-black leading-8 text-white">
          {recommendation}
        </p>
        <div className="mt-8 grid gap-3">
          {['Cite records', 'Avoid guessing', 'Route to review'].map((item) => (
            <div key={item} className="flex items-center gap-3 text-white/68">
              <Check className="h-4 w-4 text-plasma" aria-hidden="true" />
              {item}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default function SandboxPreview({ service }) {
  const Sandbox =
    service.sandbox.type === 'dashboard'
      ? DashboardSandbox
      : service.sandbox.type === 'mobile'
        ? MobileSandbox
        : service.sandbox.type === 'modernisation'
          ? ModernisationSandbox
          : service.sandbox.type === 'automation'
            ? AutomationSandbox
            : AiSandbox;

  return (
    <div className="h-full min-h-[420px] overflow-hidden rounded-[8px] border border-white/10 bg-void/68 p-4 shadow-glow">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <span className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.055] px-3 py-2 text-xs font-black uppercase text-white/64">
          <MousePointer2 className="h-4 w-4 text-plasma" aria-hidden="true" />
          Interactive sandbox
        </span>
        <span className="inline-flex items-center gap-2 text-sm font-bold text-white/68">
          <Activity className="h-4 w-4 text-ember" aria-hidden="true" />
          {service.sandbox.metric}
          <ArrowRight className="h-4 w-4 text-white/30" aria-hidden="true" />
          {service.sandbox.action}
        </span>
      </div>
      <div className="h-[calc(100%-3.5rem)]">
        <Sandbox service={service} />
      </div>
    </div>
  );
}
